/* This code was adapted from MacSites' WordPress Theme */

/*
 * Keyboard focus for in-page links (the "Skip to ..." links in header.php): after the URL's #hash
 * changes, move focus to the element it names, so the next Tab continues from there.
 *
 * Bootstrap used to be bundled above this; it is now js/bootstrap.min.js (Bootstrap 4.6.2, the
 * unmodified file from the bootstrap npm package), loaded before this file by functions.php.
 */
!function() {
    var t = -1 < navigator.userAgent.toLowerCase().indexOf("webkit")
      , e = -1 < navigator.userAgent.toLowerCase().indexOf("opera")
      , n = -1 < navigator.userAgent.toLowerCase().indexOf("msie");
    (t || e || n) && document.getElementById && window.addEventListener && window.addEventListener("hashchange", function() {
        var t, e = location.hash.substring(1);
        /^[A-z0-9_-]+$/.test(e) && (t = document.getElementById(e)) && (/^(?:a|select|input|button|textarea)$/i.test(t.tagName) || (t.tabIndex = -1),
        t.focus())
    }, !1)
}();
